solution:
function balanced(text) {
 const stack=[], pairs={")":"(","]":"[","}":"{"};
 for(const c of text) {
  if("([{ ".trim().includes(c)) stack.push(c);
  else if(c in pairs && stack.pop()!==pairs[c]) return false;
 }
 return stack.length===0;
}

