solution:
function distance(graph,start,end) {
 const q=[[start,0]], seen=new Set([start]);
 for(let h=0;h<q.length;h++) {
  const [v,d]=q[h]; if(v===end) return d;
  for(const n of graph[v]||[]) if(!seen.has(n)) {seen.add(n);q.push([n,d+1]);}
 }
 return -1;
}

