solution:
function minCoins(coins,amount) {
 const dp=Array(amount+1).fill(Infinity); dp[0]=0;
 for(let a=1;a<=amount;a++) for(const c of coins)
  if(c<=a) dp[a]=Math.min(dp[a],1+dp[a-c]);
 return Number.isFinite(dp[amount])?dp[amount]:-1;
}

