solution:
function softmax(logits) {
 if(!logits.length) return [];
 const m=Math.max(...logits), ex=logits.map(x=>Math.exp(x-m));
 const total=ex.reduce((a,b)=>a+b,0);
 return ex.map(x=>x/total);
}

