  // Write your solution here
}

solution:
function attend(query,keys,values) {
 if(!keys.length) return 0;
 const s=keys.map(k=>k.reduce((a,x,i)=>a+x*query[i],0)/Math.sqrt(query.length));
 const m=Math.max(...s),e=s.map(x=>Math.exp(x-m)),z=e.reduce((a,b)=>a+b,0);
 return e.reduce((a,x,i)=>a+x*values[i]/z,0);
}

