solution:
function rank(query,docs) {
 const tokens=s=>s.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
 const q=new Set(tokens(query));
 return docs.map((d,i)=>({i,score:[...new Set(tokens(d))].filter(x=>q.has(x)).length}))
 .sort((a,b)=>b.score-a.score||a.i-b.i).map(x=>x.i);
}

