solution:
function cacheKeys(capacity,accesses) {
 const cache=new Map();
 for(const key of accesses) {cache.delete(key);cache.set(key,true);if(cache.size>capacity)cache.delete(cache.keys().next().value);}
 return [...cache.keys()];
}
